export const SYSTEM_PROMPT = `
You are MorphUI, an advanced AI capable of generating fully functional React applications in real-time.

Your task is to generate a SINGLE FILE React component based on the user's request and the previous code context.

RULES:
1.  **Output Format**: Return ONLY the raw code for the React component. Do not include markdown code blocks (no \`\`\`tsx). Do not include explanation text.
2.  **Language**: TypeScript (TSX).
3.  **Structure**:
    *   Imports: You may use standard imports.
    *   Component: Must be exported as \`default\`.
4.  **Available Libraries** (These are pre-installed and available in the runtime environment):
    *   \`react\` (React, useState, useEffect, useRef, etc.)
    *   \`framer-motion\` (motion, AnimatePresence)
    *   \`lucide-react\` (All icons. Import like: \`import { Home, User } from 'lucide-react'\`)
    *   \`recharts\` (All charts. Import like: \`import { LineChart, Line, XAxis, ... } from 'recharts'\`)
    *   \`clsx\`, \`tailwind-merge\` (Optional)
5.  **Styling**: Use **Tailwind CSS** for all styling. Ensure high contrast, modern aesthetics, and responsive design.
6.  **Functionality**: The code must be fully functional. Implement state, effects, and interactions as requested.
7.  **Images**: Use \`https://picsum.photos/WIDTH/HEIGHT\` for placeholders.

If the user request is ambiguous, make a creative decision to build something impressive.
ALWAYS return the FULL code, do not return partial diffs.
`;

import { GoogleGenAI } from "@google/genai";
import { SYSTEM_PROMPT } from '../constants';

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateCode = async (
  prompt: string,
  currentCode: string
): Promise<string> => {
  try {
    const fullPrompt = `
      Current Code Context:
      ${currentCode}

      User Request:
      ${prompt}

      Rewrite the code to satisfy the user request. Keep existing functionality unless asked to remove it.
      Improve the design using Tailwind CSS.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Fast and capable for code
      contents: fullPrompt,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        temperature: 0.5, // Balance creativity and correctness
      },
    });

    let code = response.text || '';

    // Cleanup: Remove markdown backticks if the model ignores the system prompt
    code = code.replace(/^```tsx/g, '').replace(/^```typescript/g, '').replace(/^```/g, '').replace(/```$/g, '');

    return code.trim();

  } catch (error) {
    console.error("Gemini Code Generation Error:", error);
    throw error;
  }
};

import React from 'react';
import * as ReactDOM from 'react-dom';
import * as FramerMotion from 'framer-motion';
import * as LucideReact from 'lucide-react';
import * as Recharts from 'recharts';

// Define the execution scope
const scope: any = {
  react: React,
  'react-dom': ReactDOM,
  'framer-motion': FramerMotion,
  'lucide-react': LucideReact,
  'recharts': Recharts,
};

// Custom require function for the sandboxed environment
const customRequire = (moduleName: string) => {
  if (scope[moduleName]) {
    return scope[moduleName];
  }
  throw new Error(`Module '${moduleName}' is not available in the sandbox.`);
};

export const transformAndExecute = (code: string): React.ComponentType | null => {
  try {
    // 1. Transform TSX/ESM to CommonJS/Vanilla JS using Babel
    // @ts-ignore - Babel is loaded via CDN in index.html
    if (!window.Babel) {
      throw new Error("Babel not loaded");
    }

    // @ts-ignore
    const transformed = window.Babel.transform(code, {
      presets: ['react', 'env'],
      filename: 'file.tsx',
    }).code;

    // 2. Wrap the code in a function to execute it and capture the export
    // We create a wrapper that provides 'require', 'React', 'exports', 'module'
    const wrapperFunction = new Function('require', 'React', 'exports', 'module', transformed);

    // 3. Execute
    const module = { exports: {} as any };
    const exports = module.exports;

    wrapperFunction(customRequire, React, exports, module);

    // 4. Return the default export
    return module.exports.default || module.exports;

  } catch (error) {
    console.error("Code Compilation Error:", error);
    throw error;
  }
};

import React, { useMemo, useState, useEffect } from 'react';
import { transformAndExecute } from '../utils/codeExecution';
import { AlertCircle, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';

interface DynamicComponentProps {
  code: string;
}

class ErrorBoundary extends React.Component<
  { children: React.ReactNode; fallback: (error: Error) => React.ReactNode },
  { hasError: boolean; error: Error | null }
> {
  constructor(props: any) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidUpdate(prevProps: any) {
    if (prevProps.children !== this.props.children) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError && this.state.error) {
      return this.props.fallback(this.state.error);
    }
    return this.props.children;
  }
}

const DynamicComponent: React.FC<DynamicComponentProps> = ({ code }) => {
  const [Component, setComponent] = useState<React.ComponentType | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    try {
      setError(null);
      const compiledComponent = transformAndExecute(code);
      if (compiledComponent) {
        setComponent(() => compiledComponent);
      } else {
        throw new Error("No component returned from code.");
      }
    } catch (err: any) {
      setError(err);
      setComponent(null);
    }
  }, [code]);

  if (error) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center bg-red-950/20 p-8 text-center">
        <div className="bg-red-900/20 p-4 rounded-full mb-4">
          <AlertCircle className="h-10 w-10 text-red-500" />
        </div>
        <h3 className="text-xl font-bold text-red-200 mb-2">Compilation Error</h3>
        <p className="text-red-300 max-w-lg mb-6">{error.message}</p>
        <pre className="bg-black/50 p-4 rounded-lg text-xs text-left text-red-200 w-full max-w-2xl overflow-auto border border-red-900/50">
          {code}
        </pre>
      </div>
    );
  }

  if (!Component) {
    return (
      <div className="flex h-full w-full items-center justify-center text-slate-500">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <ErrorBoundary
      fallback={(runtimeError) => (
        <div className="flex h-full w-full flex-col items-center justify-center bg-orange-950/20 p-8">
           <div className="bg-orange-900/20 p-4 rounded-full mb-4">
            <AlertCircle className="h-10 w-10 text-orange-500" />
          </div>
          <h3 className="text-xl font-bold text-orange-200 mb-2">Runtime Error</h3>
          <p className="text-orange-300 max-w-lg">{runtimeError.message}</p>
        </div>
      )}
    >
      <Component />
    </ErrorBoundary>
  );
};

export default DynamicComponent;

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, ArrowUp, Code, StopCircle } from 'lucide-react';
import { clsx } from 'clsx'; // Assuming clsx is available or I'll implement a simple one if not, but standard React pattern uses it. Actually standard libraries restriction: I will stick to template literals if needed but clsx is usually standard. I'll use template literals to be safe.

interface CommandBarProps {
  onCommand: (command: string) => void;
  isGenerating: boolean;
  onToggleCode: () => void;
  showCode: boolean;
}

const CommandBar: React.FC<CommandBarProps> = ({ onCommand, isGenerating, onToggleCode, showCode }) => {
  const [input, setInput] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isGenerating) {
      onCommand(input.trim());
      setInput('');
    }
  };

  return (
    <div className="fixed bottom-8 left-0 right-0 z-50 flex justify-center px-4 pointer-events-none">
      <motion.div 
        layout
        className={`pointer-events-auto flex flex-col items-center w-full max-w-2xl ${isFocused ? 'scale-105' : 'scale-100'} transition-transform duration-300`}
      >
        <form 
          onSubmit={handleSubmit}
          className={`
            relative w-full flex items-center gap-2 p-2 pl-4 rounded-2xl 
            bg-slate-900/80 backdrop-blur-xl border border-white/10 shadow-2xl
            ring-1 ring-white/10 transition-all duration-300
            ${isFocused ? 'ring-blue-500/50 shadow-blue-500/20' : ''}
          `}
        >
          {isGenerating ? (
            <motion.div 
              animate={{ rotate: 360 }}
              transition={{ repeat: Infinity, duration: 2, ease: "linear" }}
              className="p-2"
            >
              <Sparkles className="w-5 h-5 text-purple-400" />
            </motion.div>
          ) : (
             <Sparkles className="w-5 h-5 text-blue-400 ml-1" />
          )}

          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            placeholder={isGenerating ? "Morphing..." : "Describe changes (e.g., 'Add a dark mode toggle')"}
            disabled={isGenerating}
            className="flex-1 bg-transparent border-none outline-none text-white placeholder-slate-400 py-3 text-lg"
          />

          <div className="flex items-center gap-1 pr-1">
             <button
              type="button"
              onClick={onToggleCode}
              className={`p-2 rounded-xl transition-colors ${showCode ? 'bg-white/20 text-white' : 'hover:bg-white/10 text-slate-400'}`}
              title="Toggle Code View"
            >
              <Code className="w-5 h-5" />
            </button>

            <button
              type="submit"
              disabled={!input.trim() || isGenerating}
              className={`
                p-2 rounded-xl transition-all duration-200
                ${input.trim() && !isGenerating 
                  ? 'bg-blue-600 text-white shadow-lg hover:bg-blue-500' 
                  : 'bg-white/5 text-slate-500 cursor-not-allowed'}
              `}
            >
              <ArrowUp className="w-5 h-5" />
            </button>
          </div>
        </form>

        <AnimatePresence>
          {isGenerating && (
             <motion.div
               initial={{ opacity: 0, y: -10 }}
               animate={{ opacity: 1, y: 0 }}
               exit={{ opacity: 0, y: 10 }}
               className="mt-3 text-xs font-medium text-purple-300 tracking-wide uppercase bg-purple-900/30 px-3 py-1 rounded-full border border-purple-500/20 backdrop-blur-md"
             >
               Generating new version...
             </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
};

export default CommandBar;

import React from 'react';
import { motion } from 'framer-motion';

interface CodeViewerProps {
  code: string;
  isVisible: boolean;
}

const CodeViewer: React.FC<CodeViewerProps> = ({ code, isVisible }) => {
