    >
      <div className="p-4 border-b border-white/10 flex justify-between items-center bg-white/5">
        <span className="text-sm font-mono text-slate-400">Component Source</span>
        <div className="flex gap-2">
          <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/50" />
          <div className="w-3 h-3 rounded-full bg-yellow-500/20 border border-yellow-500/50" />
          <div className="w-3 h-3 rounded-full bg-green-500/20 border border-green-500/50" />
        </div>
      </div>
      <div className="flex-1 overflow-auto p-4 custom-scrollbar">
        <pre className="text-xs md:text-sm font-mono text-blue-100 leading-relaxed whitespace-pre-wrap break-all">
          {code}
        </pre>
      </div>
    </motion.div>
  );
};

export default CodeViewer;

import React, { useState, useEffect } from 'react';
import { generateCode } from './services/geminiService';
import { INITIAL_CODE } from './constants';
import DynamicComponent from './components/DynamicComponent';
import CommandBar from './components/CommandBar';
import CodeViewer from './components/CodeViewer';
import { AnimatePresence } from 'framer-motion';

export default function App() {
  const [currentCode, setCurrentCode] = useState<string>(INITIAL_CODE);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showCode, setShowCode] = useState(false);
  const [history, setHistory] = useState<string[]>([INITIAL_CODE]);

  const handleCommand = async (prompt: string) => {
    setIsGenerating(true);
    try {
      const newCode = await generateCode(prompt, currentCode);

      // Update state
      setCurrentCode(newCode);
      setHistory(prev => [...prev, newCode]);
    } catch (error) {
      console.error("Failed to generate code", error);
      // We could add a toast notification here
      alert("I couldn't morph the interface this time. Please try a different command.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleToggleCode = () => {
    setShowCode(!showCode);
  };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-slate-950 text-slate-200 font-sans">
      {/* Background pattern */}
      <div className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]"></div>

      {/* Main Dynamic Content */}
      <main className="relative w-full h-full z-0 overflow-auto">
        <DynamicComponent code={currentCode} />
      </main>

      {/* Floating UI Elements */}
      <AnimatePresence>
        {showCode && <CodeViewer code={currentCode} isVisible={showCode} />}
      </AnimatePresence>

      <CommandBar 
        onCommand={handleCommand} 
        isGenerating={isGenerating} 
        onToggleCode={handleToggleCode}
        showCode={showCode}
      />

      {/* Version Indicator */}
      <div className="fixed bottom-4 left-4 z-40 text-[10px] text-slate-600 font-mono pointer-events-none">
        v{history.length}.0
      </div>
    </div>
  );
}

