import React, { useState, useEffect, ReactNode } from 'react';
import { transformAndExecute } from '../utils/codeExecution';
import { AlertCircle, Loader2 } from 'lucide-react';

interface DynamicComponentProps {
  code: string;
}

interface ErrorBoundaryProps {
  children?: ReactNode;
  fallback: (error: Error) => ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidUpdate(prevProps: ErrorBoundaryProps) {
    if (prevProps.children !== this.props.children) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError && this.state.error) {
      return this.props.fallback(this.state.error);
    }
    return this.props.children;
  }
}

const DynamicComponent: React.FC<DynamicComponentProps> = ({ code }) => {
  const [Component, setComponent] = useState<React.ComponentType | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    try {
      setError(null);
      const compiledComponent = transformAndExecute(code);
      if (compiledComponent) {
        setComponent(() => compiledComponent);
      } else {
        throw new Error("No component returned from code.");
      }
    } catch (err: any) {
      setError(err);
      setComponent(null);
    }
  }, [code]);

  if (error) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center bg-red-950/20 p-8 text-center">
        <div className="bg-red-900/20 p-4 rounded-full mb-4">
          <AlertCircle className="h-10 w-10 text-red-500" />
        </div>
        <h3 className="text-xl font-bold text-red-200 mb-2">Compilation Error</h3>
        <p className="text-red-300 max-w-lg mb-6">{error.message}</p>
        <pre className="bg-black/50 p-4 rounded-lg text-xs text-left text-red-200 w-full max-w-2xl overflow-auto border border-red-900/50">
          {code}
        </pre>
      </div>
    );
  }

  if (!Component) {
    return (
      <div className="flex h-full w-full items-center justify-center text-slate-500">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <ErrorBoundary
      fallback={(runtimeError) => (
        <div className="flex h-full w-full flex-col items-center justify-center bg-orange-950/20 p-8">
           <div className="bg-orange-900/20 p-4 rounded-full mb-4">
