          <h3 className="text-xl font-bold text-orange-200 mb-2">Runtime Error</h3>
          <p className="text-orange-300 max-w-lg">{runtimeError.message}</p>
        </div>
      )}
    >
      <Component />
    </ErrorBoundary>
  );
};

